    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []
    if not b:
        return sorted(a)

    # Merge overlapping/touching intervals in both a and b
    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = [intervals[0]]
        for start, end in intervals[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return merged

    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            next_ranges = []
            for c_start, c_end in current_ranges:
                # No overlap
                if b_end <= c_start or b_start >= c_end:
                    next_ranges.append([c_start, c_end])
                else:
                    # There is overlap, keep non-overlapping parts
                    if c_start < b_start:
                        next_ranges.append([c_start, b_start])
                    if b_end < c_end:
                        next_ranges.append([b_end, c_end])
            current_ranges = next_ranges

        result.extend(current_ranges)

    # Merge adjacent intervals in result
    if not result:
        return []
    result = sorted(result)
    merged_result = [result[0]]
    for start, end in result[1:]:
        if start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

